public static METCreateCSDTransferOrderTaskController construct()
{
    METCreateCSDTransferOrderTaskController controller = new METCreateCSDTransferOrderTaskController();

    controller.parmLoadFromSysLastValue(false);

    return controller;
}

/// <summary>
/// New object
/// </summary>
